style.css:
@-moz-document domain("needoru.com") {
/* ============================================================================
   LAYER 0: FOUNDATION & RESET
   ============================================================================ */

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    transition: all 0.3s ease;
}

/* ============================================================================
   LAYER 1: BASE BACKGROUND & SURFACES
   ============================================================================ */

body {
    background: #282a36 !important;
    color: #f8f8f2 !important;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif !important;
    line-height: 1.6 !important;
}

/* Primary content containers */
main, .main-content, .container, .wrapper {
    background: #282a36 !important;
    color: #f8f8f2 !important;
}

/* ============================================================================
   LAYER 2: ELEVATED SURFACES (Cards, Panels, Modals)
   ============================================================================ */

.card, .panel, .box, .widget,
article, section, aside,
.modal, .dialog, .popup,
.dropdown, .menu {
    background: #44475a !important;
    border: 1px solid #6272a4 !important;
    border-radius: 8px !important;
    padding: 16px !important;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3) !important;
}

/* ============================================================================
   LAYER 3: NAVIGATION & HEADER
   ============================================================================ */

header, nav, .navbar, .header,
.top-bar, .menu-bar {
    background: #44475a !important;
    border-bottom: 2px solid #bd93f9 !important;
    padding: 12px 24px !important;
}

nav a, .nav-link, .menu-item {
    color: #8be9fd !important;
    text-decoration: none !important;
    padding: 8px 16px !important;
    border-radius: 4px !important;
}

nav a:hover, .nav-link:hover, .menu-item:hover {
    background: #6272a4 !important;
    color: #bd93f9 !important;
}

/* ============================================================================
   LAYER 4: INTERACTIVE ELEMENTS (Buttons, Links, Inputs)
   ============================================================================ */

/* Primary Buttons */
button, .btn, .button,
input[type="submit"], input[type="button"] {
    background: #bd93f9 !important;
    color: #282a36 !important;
    border: none !important;
    padding: 10px 20px !important;
    border-radius: 6px !important;
    font-weight: 600 !important;
    cursor: pointer !important;
    box-shadow: 0 2px 4px rgba(189, 147, 249, 0.3) !important;
}

button:hover, .btn:hover, .button:hover,
input[type="submit"]:hover, input[type="button"]:hover {
    background: #ff79c6 !important;
    transform: translateY(-2px) !important;
    box-shadow: 0 4px 8px rgba(255, 121, 198, 0.4) !important;
}

/* Links */
a {
    color: #8be9fd !important;
    text-decoration: none !important;
    border-bottom: 1px solid transparent !important;
}

a:hover {
    color: #ff79c6 !important;
    border-bottom-color: #ff79c6 !important;
}

/* Input Fields */
input, textarea, select {
    background: #44475a !important;
    color: #f8f8f2 !important;
    border: 2px solid #6272a4 !important;
    border-radius: 4px !important;
    padding: 8px 12px !important;
}

input:focus, textarea:focus, select:focus {
    outline: none !important;
    border-color: #bd93f9 !important;
    box-shadow: 0 0 0 3px rgba(189, 147, 249, 0.2) !important;
}

/* ============================================================================
   LAYER 5: TYPOGRAPHY HIERARCHY
   ============================================================================ */

h1, h2, h3, h4, h5, h6 {
    color: #f8f8f2 !important;
    font-weight: 700 !important;
    margin-bottom: 16px !important;
}

h1 { 
    font-size: 2.5em !important; 
    color: #bd93f9 !important;
    border-bottom: 3px solid #bd93f9 !important;
    padding-bottom: 8px !important;
}

h2 { 
    font-size: 2em !important; 
    color: #ff79c6 !important; 
}

h3 { 
    font-size: 1.75em !important; 
    color: #8be9fd !important; 
}

p, span, div, li {
    color: #f8f8f2 !important;
}

/* Muted text */
.muted, .secondary, .subtitle,
small, .text-muted {
    color: #6272a4 !important;
}

/* ============================================================================
   LAYER 6: STATE INDICATORS (Success, Warning, Error)
   ============================================================================ */

/* Success states */
.success, .alert-success, .message-success,
.status-success, .badge-success {
    background: rgba(80, 250, 123, 0.2) !important;
    color: #50fa7b !important;
    border: 1px solid #50fa7b !important;
}

/* Warning states */
.warning, .alert-warning, .message-warning,
.status-warning, .badge-warning {
    background: rgba(241, 250, 140, 0.2) !important;
    color: #f1fa8c !important;
    border: 1px solid #f1fa8c !important;
}

/* Error states */
.error, .alert-error, .message-error,
.status-error, .badge-error,
.alert-danger, .badge-danger {
    background: rgba(255, 85, 85, 0.2) !important;
    color: #ff5555 !important;
    border: 1px solid #ff5555 !important;
}

/* ============================================================================
   LAYER 7: SPECIAL COMPONENTS
   ============================================================================ */

/* Tables */
table {
    width: 100% !important;
    border-collapse: collapse !important;
    background: #44475a !important;
}

th {
    background: #6272a4 !important;
    color: #f8f8f2 !important;
    padding: 12px !important;
    text-align: left !important;
    font-weight: 600 !important;
}

td {
    padding: 10px 12px !important;
    border-bottom: 1px solid #6272a4 !important;
    color: #f8f8f2 !important;
}

tr:hover {
    background: rgba(189, 147, 249, 0.1) !important;
}

/* Code blocks */
code, pre, .code {
    background: #282a36 !important;
    color: #50fa7b !important;
    padding: 4px 8px !important;
    border-radius: 4px !important;
    font-family: 'Courier New', monospace !important;
    border: 1px solid #6272a4 !important;
}

/* Badges & Tags */
.badge, .tag, .label {
    background: #bd93f9 !important;
    color: #282a36 !important;
    padding: 4px 12px !important;
    border-radius: 12px !important;
    font-size: 0.85em !important;
    font-weight: 600 !important;
}

/* ============================================================================
   LAYER 8: ANIMATIONS & MICRO-INTERACTIONS
   ============================================================================ */

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
}

.card, .panel, .box, article {
    animation: fadeIn 0.4s ease-out !important;
}

/* Scrollbar styling */
::-webkit-scrollbar {
    width: 12px !important;
    height: 12px !important;
}

::-webkit-scrollbar-track {
    background: #282a36 !important;
}

::-webkit-scrollbar-thumb {
    background: #6272a4 !important;
    border-radius: 6px !important;
}

::-webkit-scrollbar-thumb:hover {
    background: #bd93f9 !important;
}

/* Selection styling */
::selection {
    background: #bd93f9 !important;
    color: #282a36 !important;
}

/* ============================================================================
   LAYER 9: RESPONSIVE UTILITIES & OVERRIDES
   ============================================================================ */

/* Ensure high contrast for accessibility */
.text-primary, .primary-text {
    color: #f8f8f2 !important;
}

.text-accent, .accent-text {
    color: #bd93f9 !important;
}

/* Background overrides */
.bg-dark, .dark-bg {
    background: #282a36 !important;
}

.bg-elevated, .elevated-bg {
    background: #44475a !important;
}

/* Border utilities */
.border, .bordered {
    border: 1px solid #6272a4 !important;
}

/* Shadow utilities */
.shadow {
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3) !important;
}

.shadow-lg {
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.4) !important;
}

/* ============================================================================
   END OF GLOBAL NEEDORU THEME
   ============================================================================ */
}
